"""12 类标准投诉类型及 docx 分项映射。"""

from __future__ import annotations

COMPLAINT_TYPES: tuple[str, ...] = (
    "信号配时不合理",
    "左转掉头通行困难",
    "直行放行不足",
    "信号相位/放行顺序不合理",
    "车道设置与渠化问题",
    "信号设施遮挡或标识不清",
    "信号故障或运行异常",
    "施工与临时交通影响",
    "拥堵与通行效率低",
    "行人非机动车冲突",
    "监控执法相关诉求",
    "其他综合诉求",
)

_TYPE_RULES: list[tuple[str, tuple[str, ...]]] = [
    ("信号配时不合理", ("配时不合理", "配时不科学", "配时设置", "配时调整", "配时逻辑", "配时比例", "配时方案", "信号周期", "绿灯时长", "红灯等待", "红灯时长", "红灯周期", "绿信比", "时长分配", "信号时长", "等待时间")),
    ("左转掉头通行困难", ("左转", "掉头")),
    ("直行放行不足", ("直行放行", "直行绿灯", "主路路权", "直行与左转同时", "直行与左转共用")),
    ("信号相位/放行顺序不合理", ("放行顺序", "放行逻辑", "相位", "错时放行", "同时放行", "分向放行", "分离控制", "同步放行", "控制模式", "控制逻辑", "信号逻辑", "变灯逻辑", "不同步", "联动", "绿波", "空档期", "全红", "黄灯闪烁", "黄闪", "无灯", "拆除信号", "取消信号", "设置必要性", "设置密度", "设置规范")),
    ("车道设置与渠化问题", ("车道设置", "车道功能", "渠化", "可变车道", "潮汐车道", "左转车道", "右转车道", "车道数量", "车道规划", "标线", "待转区", "待转线", "导流线", "拓宽", "车道缩减", "混行")),
    ("信号设施遮挡或标识不清", ("遮挡", "标识不清", "指示不明", "可视", "读秒", "倒计时", "颜色偏", "高度过低", "灯体较小", "亮度不足", "位置不显眼", "新国标")),
    ("信号故障或运行异常", ("故障", "异常", "不切换", "不亮", "缺失", "撤除")),
    ("施工与临时交通影响", ("施工", "临时信号", "围挡", "地铁", "改道", "占用车道", "封闭")),
    ("拥堵与通行效率低", ("拥堵", "压车", "积压", "通行效率", "排队")),
    ("行人非机动车冲突", ("行人", "非机动车", "人行", "机非", "过街")),
    ("监控执法相关诉求", ("监控", "执法", "违章", "闯红灯")),
    ("其他综合诉求", ("特权", "专用", "内部车辆", "答复", "咨询", "通话录音")),
]


def classify_complaint_type(topic_raw: str) -> str:
    text = (topic_raw or "").strip()
    if not text:
        return "其他综合诉求"
    matched: list[tuple[int, str]] = []
    for type_name, keywords in _TYPE_RULES:
        for kw in keywords:
            if kw in text:
                matched.append((len(kw), type_name))
                break
    if not matched:
        return "其他综合诉求"
    matched.sort(key=lambda x: -x[0])
    chosen = matched[0][1]
    if chosen == "拥堵与通行效率低":
        for _, t in matched:
            if t == "信号配时不合理":
                return "信号配时不合理"
    if chosen == "左转掉头通行困难":
        for _, t in matched:
            if t == "直行放行不足" and "直行" in text:
                return "直行放行不足"
    return chosen
